  nodes.add instr("PLD", amImplied)  # $C0769A: PLD
  nodes.add instr("RTL", amImplied)  # $C0769B: RTL
  result = assemble(nodes, 0xC07477'u32,
                    FlagState(m8: false, x8: false, emulation: false))
